// Brand-icon lookup for the persistent UI (shop tiles, inventory slots,
// the order-build tray, and the recipe guide). The transient message-strip
// toasts (e.g. "Bought 10 lemons!") are plain text -- no icons or emoji
// (2026-09-09, per Kayla: no emoji anywhere in the game).
const SUPPLY_ICON_SVGS = {
  cups: EMPTY_CUP_SVG,
  lemons: LEMON_SVG,
  ice: ICE_SVG,
  sugar: SUGAR_SVG,
  // Split from the iced-tea glass (2026-08-28) -- the glass is now reserved
  // for the finished-drink/order icon only (see RECIPES' icedTea/sweetTea
  // .icon below, still TEA_CUP_SVG), so the raw supply reads as an actual
  // tea bag in the shop tile, inventory slot, and recipe-ingredient row.
  tea: TEA_BAG_SVG
};

function ingredientIconHTML(type) {
  return "<span>" + SUPPLY_ICON_SVGS[type] + "</span>";
}

// Fills in the shop tiles' and inventory slots' icon markup from
// SUPPLY_ICON_SVGS -- index.html only has to know each tile/slot's
// data-supply type, so there's exactly one place (SUPPLY_ICON_SVGS above)
// that defines what each ingredient icon looks like. The order-build tray
// and recipe guide already worked this way; this brings the shop and
// inventory in line with them (2026-09-10, per Kayla's icon refresh --
// previously index.html had its own separate, hand-pasted copy of these
// SVGs, which is exactly how the shop/inventory art could silently drift
// out of sync with an icon update like this one).
function populateSupplyIcons() {
  document.querySelectorAll(".shop-icon, .inv-icon").forEach(function (el) {
    const slot = el.closest("[data-supply]");
    const type = slot && slot.getAttribute("data-supply");
    if (type && SUPPLY_ICON_SVGS[type]) {
      el.innerHTML = SUPPLY_ICON_SVGS[type];
    }
  });
}

