const DEFAULT_SHIRT_COLORS = [
  '#258BFF', // Blue
  '#FF2525', // Red
  '#FF25BA', // Pink
  '#FF9D25', // Orange
  '#FFF025', // Yellow
  '#49FF25', // Green
  '#27F5FF', // Cyan
  '#9D25FF'  // Purple
];
// Darkest tone removed -- too little contrast against the line art (2026-09-09, per Kayla).
const DEFAULT_SKIN_TONES = ['#FBE0D2', '#F3C9AE', '#DFA77F', '#B97850', '#875037'];

// Natural hair-color palette, randomized independently of hair style/variant
// (a girl or boy hairstyle can land on any of these).
const DEFAULT_HAIR_COLORS = [
  '#2B2118', // Black
  '#4A2E1D', // Dark Brown
  '#6F4123', // Chestnut Brown
  '#9C6B3F', // Caramel Blonde
  '#D9A857', // Blonde
  '#A8462A'  // Auburn/Red
];

// How many alternate hairstyle variants exist within each hairStyle.
const HAIR_VARIANT_COUNT = {
  girl: 6,
  boy: 5
};

const HAIR_STYLES = ['girl', 'boy'];

/**
 * Fill in the SVG template from a config object.
 * config: {
 *   shirtColor: '#rrggbb',
 *   skinColor: '#rrggbb',
 *   hairStyle: 'girl' | 'boy',
 *   hairVariant: 1-6 (girl) or 1-5 (boy) -- which single hairstyle to show,
 *   hairColor: '#rrggbb'  (optional - defaults to a random pick from DEFAULT_HAIR_COLORS),
 *   mouthStyle: 'straight' | 'smile'  (optional - defaults to 'smile'; every
 *               customer starts smiling, see setCharacterMouth to change it later)
 * }
 * Returns a finished SVG markup string.
 */
function generateCharacterSVG(config) {
  const hairColor = config.hairColor || pickRandom(DEFAULT_HAIR_COLORS);
  const mouthStyle = config.mouthStyle || 'smile';

  let svg = CHARACTER_BUILD_SVG_TEMPLATE
    .split('{{SHIRT_COLOR}}').join(config.shirtColor)
    .split('{{SKIN_COLOR}}').join(config.skinColor)
    .split('{{HAIR_COLOR}}').join(hairColor)
    .split('{{MOUTH_STRAIGHT_DISPLAY}}').join(mouthStyle === 'straight' ? 'inline' : 'none')
    .split('{{MOUTH_SMILE_DISPLAY}}').join(mouthStyle === 'smile' ? 'inline' : 'none');

  // Exactly one Girl-Hair-N and exactly one Boy-Hair-N variant is visible;
  // every other variant (both within the chosen style and the other style)
  // is hidden.
  for (let i = 1; i <= HAIR_VARIANT_COUNT.girl; i++) {
    const show = config.hairStyle === 'girl' && config.hairVariant === i;
    svg = svg.split('{{GIRL_HAIR_' + i + '_DISPLAY}}').join(show ? 'inline' : 'none');
  }
  for (let i = 1; i <= HAIR_VARIANT_COUNT.boy; i++) {
    const show = config.hairStyle === 'boy' && config.hairVariant === i;
    svg = svg.split('{{BOY_HAIR_' + i + '_DISPLAY}}').join(show ? 'inline' : 'none');
  }

  return svg;
}

function pickRandom(list) {
  return list[Math.floor(Math.random() * list.length)];
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

/**
 * Build a random config from the given shirt-color / skin-tone / hair-color
 * lists (falls back to the DEFAULT_* lists above if omitted). Every
 * character starts with mouthStyle 'smile' -- use setCharacterMouth to
 * switch a spawned character to the straight mouth later.
 */
function randomCharacterConfig(shirtColors, skinTones, hairColors) {
  const hairStyle = pickRandom(HAIR_STYLES);
  return {
    shirtColor: pickRandom(shirtColors || DEFAULT_SHIRT_COLORS),
    skinColor: pickRandom(skinTones || DEFAULT_SKIN_TONES),
    hairStyle: hairStyle,
    hairVariant: randomInt(1, HAIR_VARIANT_COUNT[hairStyle]),
    hairColor: pickRandom(hairColors || DEFAULT_HAIR_COLORS),
    mouthStyle: 'smile'
  };
}

/**
 * Convenience one-shot: random config -> finished SVG string. Called at the
 * three customer-spawn sites below (spawnCustomer, spawnTutorialCustomer,
 * spawnScriptedTimedCustomer) to give each new customer a fresh random look,
 * in place of the old fixed 4-character lineup.
 */
function createRandomCharacterSVG(shirtColors, skinTones, hairColors) {
  return generateCharacterSVG(randomCharacterConfig(shirtColors, skinTones, hairColors));
}

/**
 * Switch an already-inserted character's mouth between 'smile' and
 * 'straight' without rebuilding the whole SVG. container is any ancestor
 * element of the character markup (e.g. a customer's root .customer div, or
 * its .customer-face child) -- both mouth shapes always exist in the markup
 * (only one is ever displayed), so this just toggles which one shows.
 */
function setCharacterMouth(container, mouthStyle) {
  if (!container) {
    return;
  }
  const straight = container.querySelector('.cb-mouth-straight');
  const smile = container.querySelector('.cb-mouth-smile');
  if (straight) {
    straight.style.display = mouthStyle === 'straight' ? 'inline' : 'none';
  }
  if (smile) {
    smile.style.display = mouthStyle === 'smile' ? 'inline' : 'none';
  }
}


