let spentToday = 0;

// Simple flat daily rate applied to whatever's in savings each time a new
// day opens (see startNextDay) -- re-added per Kayla ("add the interest
// growth to savings again"); the exact rate wasn't specified this round,
// so 2%/day is a placeholder flagged for her to confirm/adjust.
const SAVINGS_INTEREST_RATE = 0.04; // 4%/day (2026-09-23, per Kayla; was 2%)

let spawnTimeout;
let customerTickInterval;

let isPaused = true;

let customers = [];
let nextCustomerId = 1;

// ==========================================
// PAUSE / RESUME
// Any popup (recipe guide, level up, restart
// confirm, tutorial) pauses customer spawning
// and customer patience while it's open.
// ==========================================

function pauseGame() {
  isPaused = true;
  document.getElementById("modalBackdrop").classList.remove("hidden");
}

function resumeGame() {
  isPaused = false;
  document.getElementById("modalBackdrop").classList.add("hidden");
}

// ==========================================
// START GAME
// ==========================================

document.addEventListener("DOMContentLoaded", function () {
  // Recap popup's savings hint names the live interest rate, so it always
  // matches SAVINGS_INTEREST_RATE if that's changed again.
  const rateEl = document.getElementById("dayRecapInterestRate");
  if (rateEl) rateEl.textContent = Math.round(SAVINGS_INTEREST_RATE * 100) + "%";
  populateSupplyIcons();
  populateRecipeGuide();
  updateDisplay();

  // These loops run continuously but no-op while isPaused is true,
  // so it's safe to start them before the tutorial is dismissed.
  spawnLoop();
  startCustomerTicker();

  // Kiosk auto-launch: the Intuiface home screen's "play" action opens this
  // page with ?tutorial=1 appended to its URL. When that's present, this is
  // a fresh arrival from the home screen -- skip the Start/Tutorial choice
  // and jump straight into the guided walkthrough. Without it (a reload, or
  // any other way this page happens to load) the normal intro modal shows,
  // same as always, and the player can pick Start or Tutorial themselves.
  // The in-game restart button never touches the URL; it resets and
  // returns to this same intro popup (see confirmRestart).
  const launchParams = new URLSearchParams(window.location.search);

  // Testing shortcut (2026-09-23, per Kayla): jump straight to a later day
  // by ending the URL in #day3 (or ?day=3). Unlocks every recipe/supply up
  // to that day, skips the intro popup and tutorial, and starts that day
  // live with the normal $10 starting cash. Any number outside 1..last day
  // is ignored and the game loads normally.
  //
  // Add "result" to land on that day's end-of-day results popup instead
  // (2026-09-23, per Kayla): #day4result, #day6result (#day6results and
  // ?day=6&result=1 work too). Shows the CLOSED sign, then the recap, just
  // like finishing the day for real -- so #day4result's "Start Day 5"
  // button also leads into the Lemon Tea unlock popup, and #day6result
  // opens the finale.
  const skipDay = getSkipToDayFromUrl(launchParams);
  if (skipDay) {
    skipToDay(skipDay, getSkipToResultFromUrl(launchParams));
    return;
  }

  if (launchParams.get("tutorial") === "1") {
    pauseGame();
    startTutorial();
  } else {
    showTutorial();
  }
});

// Reads #dayN / #day=N from the hash, or ?day=N from the query string.
function getSkipToDayFromUrl(params) {
  const hashMatch = window.location.hash.match(/day=?(\d+)/i);
  const raw = hashMatch ? hashMatch[1] : params.get("day");
  const n = parseInt(raw, 10);
  if (!n || n < 1 || n > GAME_DAYS.length) return null;
  return n;
}

// True when the URL asks for that day's results popup: #day6result /
// #day6results / #day6-result, or ?day=6&result=1.
function getSkipToResultFromUrl(params) {
  if (/day=?\d+[-_]?results?\b/i.test(window.location.hash)) return true;
  return params.get("result") === "1" || params.has("results");
}

function skipToDay(n, showResult) {
  currentDay = n;
  // Reveal every supply unlocked on or before day n (tea, etc.).
  for (let i = 0; i < n; i++) {
    revealNewSupplies(GAME_DAYS[i]);
  }
  populateRecipeGuide();
  updateDisplay();

  if (showResult) {
    // Straight to the end of day n: CLOSED sign, then the results popup.
    endDay();
    return;
  }

  resumeGame();
  showMessage("Test shortcut: jumped to Day " + n + "!");
}

// Editing the #day part of the URL doesn't reload the page on its own, so
// reload it ourselves -- lets Kayla just change #day3 to #day5 and hit Enter.
window.addEventListener("hashchange", function () {
  window.location.reload();
});

function showTutorial() {
  pauseGame();
  document.getElementById("tutorialBox").classList.remove("hidden");
}

function startGame() {
  document.getElementById("tutorialBox").classList.add("hidden");
  resumeGame();
}

