// Returns a rect-like object (duck-typed to getBoundingClientRect(), same
// interface a real DOM element exposes) spanning the union of several
// elements' on-screen boxes at once -- lets a tutorial spotlight target
// more than one element (2026-09-21, per Kayla: get the "Shop" header
// included in that step's highlight, not just the card column below it).
// Returns null if none of the elements exist, same as a missing target.
function unionRect(elements) {
  const rects = elements.filter(Boolean).map(function (el) { return el.getBoundingClientRect(); });
  if (!rects.length) {
    return null;
  }
  const left = Math.min.apply(null, rects.map(function (r) { return r.left; }));
  const top = Math.min.apply(null, rects.map(function (r) { return r.top; }));
  const right = Math.max.apply(null, rects.map(function (r) { return r.right; }));
  const bottom = Math.max.apply(null, rects.map(function (r) { return r.bottom; }));
  return {
    getBoundingClientRect: function () {
      return { left: left, top: top, right: right, bottom: bottom, width: right - left, height: bottom - top };
    }
  };
}

// Returns a rect-like object covering just the wood counter panel at the
// bottom of the stand -- the tan ledge + brown counter face painted into
// stand.svg -- rather than the whole stand (awning included) or just the
// supply cards sitting on it (2026-09-21, per Kayla: "highlight the
// entire bottom of the stand, the wood part. Not just the cards."). 50.5%
// matches the ledge's top edge, the same value the CLOSED sign anchors to
// (see .closed-sign in style.css).
function standWoodRect() {
  const stand = document.querySelector(".stand");
  if (!stand) {
    return null;
  }
  const r = stand.getBoundingClientRect();
  const woodTop = r.top + r.height * 0.505;
  return {
    getBoundingClientRect: function () {
      return { left: r.left, top: woodTop, right: r.right, bottom: r.bottom, width: r.width, height: r.bottom - woodTop };
    }
  };
}

// Decorative-only customer shown just for the "Customers" spotlight step
// (2026-09-21, per Kayla: the lane was empty when this step lit up, which
// didn't read as "customers line up here"). Not pushed onto the real
// `customers` array and not clickable -- the tutorial's full-stage click
// blocker already sits above it regardless -- purely a visual prop,
// cleared out by hideTutorialPoint() like the rest of this step's UI.
function spawnTutorialDemoCustomer() {
  if (tutorialDemoCustomerEl) {
    return;
  }
  const recipe = recipesUnlockedByDay(currentDay)[0] || RECIPES[0];
  const face = createRandomCharacterSVG();
  const el = buildCustomerElement(recipe, face, -1);
  el.onclick = null;
  document.getElementById("customerLane").appendChild(el);
  tutorialDemoCustomerEl = el;

  positionCustomer({ element: el }, 0);
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      el.classList.add("parked");
    });
  });
}

function startTutorial() {
  document.getElementById("tutorialBox").classList.add("hidden");
  document.getElementById("modalBackdrop").classList.add("hidden");

  tutorialActive = true;
  tutorialFirstServePending = true;
  tutorialPointStep = -1;

  tutorialNext();
}

function tutorialNext() {
  tutorialPointStep += 1;

  if (tutorialPointStep >= TUTORIAL_POINTS.length) {
    beginTutorialLive();
    return;
  }

  showTutorialPoint(TUTORIAL_POINTS[tutorialPointStep]);
}

function showTutorialPoint(point) {
  if (typeof point.onShow === "function") {
    point.onShow();
  }

  const targetEl = point.target();

  if (!targetEl) {
    tutorialNext();
    return;
  }

  document.getElementById("tutorialClickBlocker").classList.remove("hidden");
  document.getElementById("tutorialHighlight").classList.remove("hidden");

  const card = document.getElementById("tutorialPointCard");
  card.classList.remove("hidden");
  document.getElementById("tutorialPointTitle").textContent = point.title || "";
  document.getElementById("tutorialPointText").textContent = point.text;
  document.getElementById("tutorialNextBtn").textContent = point.buttonLabel || "Next";

  positionTutorialSpotlight(targetEl, card, point.side);
}

// Converts a target element's on-screen rect into the stage's own
// unscaled 1920x1080 coordinate space (the stage is scaled down to fit
// the window via CSS transform -- see .game-container in style.css), then
// positions the spotlight box and the popup card relative to it.
function positionTutorialSpotlight(targetEl, card, side) {
  const stage = document.querySelector(".game-container");
  const stageRect = stage.getBoundingClientRect();
  const scale = stageRect.width / STAGE_W;
  const targetRect = targetEl.getBoundingClientRect();

  const left = (targetRect.left - stageRect.left) / scale;
  const top = (targetRect.top - stageRect.top) / scale;
  const width = targetRect.width / scale;
  const height = targetRect.height / scale;

  const pad = 10;
  const highlight = document.getElementById("tutorialHighlight");
  highlight.style.left = (left - pad) + "px";
  highlight.style.top = (top - pad) + "px";
  highlight.style.width = (width + pad * 2) + "px";
  highlight.style.height = (height + pad * 2) + "px";

  const cardWidth = card.offsetWidth || 320;
  const cardHeight = card.offsetHeight || 160;
  const gap = 24;

  let cardLeft;
  let cardTop;

  if (side === "left") {
    cardLeft = left - gap - cardWidth;
    cardTop = top + height / 2 - cardHeight / 2;
  } else if (side === "right") {
    cardLeft = left + width + gap;
    cardTop = top + height / 2 - cardHeight / 2;
  } else if (side === "top") {
    cardLeft = left + width / 2 - cardWidth / 2;
    cardTop = top - gap - cardHeight;
  } else {
    // bottom
    cardLeft = left + width / 2 - cardWidth / 2;
    cardTop = top + height + gap;
  }

  // Keep the card fully inside the stage.
  cardLeft = Math.max(16, Math.min(cardLeft, STAGE_W - cardWidth - 16));
  cardTop = Math.max(16, Math.min(cardTop, STAGE_H - cardHeight - 16));

  card.style.left = cardLeft + "px";
  card.style.top = cardTop + "px";
}

function hideTutorialPoint() {
  document.getElementById("tutorialClickBlocker").classList.add("hidden");
  document.getElementById("tutorialHighlight").classList.add("hidden");
  document.getElementById("tutorialPointCard").classList.add("hidden");

  // Clear the "Customers" step's decorative demo customer, if one was
  // spawned (see spawnTutorialDemoCustomer) -- it's only ever meant to be
  // on screen for that one spotlight step, and beginTutorialLive() spawns
  // the real first practice customer right after this runs.
  if (tutorialDemoCustomerEl) {
    tutorialDemoCustomerEl.remove();
    tutorialDemoCustomerEl = null;
  }
}

function beginTutorialLive() {
  hideTutorialPoint();
  resumeGame();
  spawnTutorialCustomer(
    "classic",
    "This customer ordered a Classic Lemonade. Buy the supplies, build the order, then tap the customer to serve them!"
  );
}

// A scripted customer used during the guided-practice steps: parked in
// the front slot with its patience timer disabled (see noPatience in
// startCustomerTicker) so the player can take as long as they need.
function spawnTutorialCustomer(recipeId, calloutText) {
  tutorialLiveStep = recipeId;

  const recipe = RECIPES.find(function (r) { return r.id === recipeId; });
  const face = createRandomCharacterSVG();
  const id = nextCustomerId++;
  const el = buildCustomerElement(recipe, face, id);

  document.getElementById("customerLane").appendChild(el);

  const customer = {
    id: id,
    element: el,
    recipe: recipe,
    remainingMs: PATIENCE_MS,
    warned: false,
    noPatience: true,
    isTutorialCustomer: true,
    // The tutorial's practice customer counts as Day 1's first customer
    // (2026-09-23, per Kayla): serving them leaves 4 more, so tutorial
    // players see 5 total, same as players who skip. See serveCustomer
    // and skipTutorial.
    countsTowardDay: true,
    resolved: false
  };
  customers.push(customer);
  tutorialCustomerId = id;
  customersSpawnedToday += 1;

  positionCustomer(customer, 0);
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      el.classList.add("parked");
    });
  });
  updateCustomerReadiness(customer);

  // The customer slides in over .5s (see .customer's `right` transition in
  // style.css) -- wait for it to land before measuring its position, or
  // the callout would anchor to its off-screen starting spot instead.
  setTimeout(function () {
    showTutorialCallout(el, calloutText);
  }, 600);
}

// Two ordinary customers, spawned once the player has practiced an order --
// after this the tutorial hands control back to the regular spawn loop.
// Their patience timer matches whatever the day they're about to play
// actually uses (see noPatience on GAME_DAYS) -- Day 1 has no timer at all,
// so these stay timer-free too rather than teaching a mechanic Day 1 won't
// show.
function spawnScriptedTimedCustomer() {
  const availableRecipes = recipesUnlockedByDay(currentDay);
  const recipe = availableRecipes[Math.floor(Math.random() * availableRecipes.length)];
  const face = createRandomCharacterSVG();
  const id = nextCustomerId++;
  const el = buildCustomerElement(recipe, face, id);

  document.getElementById("customerLane").appendChild(el);

  const customer = {
    id: id,
    element: el,
    recipe: recipe,
    remainingMs: PATIENCE_MS,
    warned: false,
    noPatience: !!getCurrentDayDef().noPatience,
    isTutorialCustomer: true,
    resolved: false
  };
  customers.push(customer);

  positionCustomer(customer, customers.length - 1);
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      el.classList.add("parked");
    });
  });
  updateCustomerReadiness(customer);

  return customer;
}

function showTutorialCallout(customerEl, text) {
  const callout = document.getElementById("tutorialCallout");
  callout.classList.remove("hidden");
  document.getElementById("tutorialCalloutText").textContent = text;

  const stage = document.querySelector(".game-container");
  const stageRect = stage.getBoundingClientRect();
  const scale = stageRect.width / STAGE_W;
  const targetRect = customerEl.getBoundingClientRect();

  const left = (targetRect.left - stageRect.left) / scale;
  const top = (targetRect.top - stageRect.top) / scale;
  const width = targetRect.width / scale;

  const cardWidth = callout.offsetWidth || 260;
  let cardLeft = left + width / 2 - cardWidth / 2;
  cardLeft = Math.max(16, Math.min(cardLeft, STAGE_W - cardWidth - 16));

  callout.style.left = cardLeft + "px";
  callout.style.top = (top - 18) + "px"; // transform: translateY(-100%) lifts it clear above
}

function hideTutorialCallout() {
  document.getElementById("tutorialCallout").classList.add("hidden");
}

// Runs fn immediately, unless the first-challenge cheer popup is showing --
// in that case it waits, so a tutorial customer served at the exact moment
// the $3 goal completes doesn't spawn the next step underneath that modal.
function runAfterTutorialCheer(fn) {
  const cheerBox = document.getElementById("tutorialCheerBox");
  if (cheerBox && !cheerBox.classList.contains("hidden")) {
    setTimeout(function () { runAfterTutorialCheer(fn); }, 300);
    return;
  }
  fn();
}

// The tutorial now ends right after the first served customer's "nice
// job" cheer popup (2026-09-23, per Kayla: no need to walk them through
// more orders). Closing that popup drops the player straight into Day 1.
// The old Sweetened Lemonade practice step and the two scripted follow-up
// customers (finishTutorialIntro / spawnScriptedTimedCustomer) are no
// longer reached -- left in place, unused.
function advanceTutorialLiveStep() {
  hideTutorialCallout();
  tutorialLiveStep = null;
  tutorialCustomerId = null;
  tutorialActive = false; // hands spawning back to the regular Day 1 loop
}

function advanceTutorialLiveStepOld() {
  if (tutorialLiveStep === "classic") {
    setTimeout(function () {
      runAfterTutorialCheer(function () {
        spawnTutorialCustomer("sugar", "Nice! Now complete this customer's order for a Sweetened Lemonade.");
      });
    }, 500);
  } else if (tutorialLiveStep === "sugar") {
    tutorialLiveStep = null;
    tutorialCustomerId = null;
    setTimeout(function () {
      runAfterTutorialCheer(finishTutorialIntro);
    }, 500);
  }
}

function finishTutorialIntro() {
  hideTutorialCallout();

  spawnScriptedTimedCustomer();
  const lastCustomer = spawnScriptedTimedCustomer();

  // Same slide-in delay as spawnTutorialCustomer -- wait for the customer
  // to reach its parked spot before anchoring the callout to it.
  setTimeout(function () {
    showTutorialCallout(lastCustomer.element, "Customers don't like to wait — serve them quickly before they leave your stand!");

    setTimeout(function () {
      hideTutorialCallout();
    }, 4500);
  }, 600);

  // Hand spawning back to the regular loop -- round 1 continues as usual.
  tutorialActive = false;
}

function skipTutorial() {
  hideTutorialPoint();
  hideTutorialCallout();
  document.getElementById("tutorialBox").classList.add("hidden");
  document.getElementById("tutorialCheerBox").classList.add("hidden");

  document.getElementById("customerLane").innerHTML = "";
  // Give back the Day 1 slot of any practice customer who's being cleared
  // away unserved, so skipping still leaves the full 5 customers.
  customers.forEach(function (c) {
    if (c.countsTowardDay && !c.resolved) customersSpawnedToday -= 1;
  });
  customers = [];

  tutorialActive = false;
  tutorialLiveStep = null;
  tutorialCustomerId = null;
  tutorialFirstServePending = false;

  resumeGame();
}

function showTutorialCheer(text) {
  document.getElementById("tutorialCheerText").textContent = text;
  document.getElementById("tutorialCheerIcon").innerHTML = TROPHY_SVG;

  pauseGame();
  document.getElementById("tutorialCheerBox").classList.remove("hidden");
  updateDisplay();
}

function closeTutorialCheer() {
  document.getElementById("tutorialCheerBox").classList.add("hidden");
  resumeGame();
  updateDisplay();
}

// ==========================================
// BUY SUPPLIES
// ==========================================

function buySupplies(type) {
  const supply = SUPPLIES[type];

  if (cash < supply.price) {
    showMessage("Not enough cash for more " + supply.name.toLowerCase() + "!");
    return;
  }

  cash -= supply.price;
  totalSpent += supply.price;
  spentToday += supply.price;
  inventory[type] += supply.buyAmount;

  showMessage("Bought " + supply.buyAmount + " " + supply.name.toLowerCase() + "!");

  updateDisplay();
}

// ==========================================
// BUILD THE ORDER (tap ingredients on the counter)
// ==========================================

function addToBuild(type) {
  if (inventory[type] <= 0) {
    showMessage("You're out of " + SUPPLIES[type].name.toLowerCase() + "! Buy more first.");
    return;
  }

  inventory[type] -= 1;
  build[type] += 1;
  buildOrder.push(type);

  updateDisplay();
}

function undoLastIngredient() {
  if (buildOrder.length === 0) {
    return;
  }

  const type = buildOrder.pop();
  build[type] -= 1;
  inventory[type] += 1;

  updateDisplay();
}

function buildMatchesRecipe(recipe) {
  for (const type of SUPPLY_TYPES) {
    const needed = recipe.needs[type] || 0;
    if (build[type] !== needed) {
      return false;
    }
  }
  return true;
}

function updateBuildDisplay() {
  const container = document.getElementById("buildDisplay");
  const hasAnything = SUPPLY_TYPES.some(function (type) { return build[type] > 0; });

  if (!hasAnything) {
    container.innerHTML = '<span class="build-placeholder" id="buildPlaceholder">Tap ingredients below to build an order</span>';
    return;
  }

  // Icons appear in the order they were tapped (2026-09-23, per Kayla) --
  // was grouped by SUPPLY_TYPES (always cup, lemon, ice...), which made
  // Undo confusing since it removes the last TAPPED item, not the last one
  // shown. buildOrder is already the tap history Undo pops from.
  let html = "";
  buildOrder.forEach(function (type) {
    html += '<span class="build-icon build-icon-svg">' + SUPPLY_ICON_SVGS[type] + "</span>";
  });

  container.innerHTML = html;
}

// ==========================================
// CUSTOMER QUEUE (FIFO, diner-dash style)
// Position in the array = position in line.
// New customers always join at the back.
// When anyone leaves (served OR times out),
// everyone behind them shifts forward.
// ==========================================

const PATIENCE_MS = 15000;
const WARNING_MS = 5000;
const TICK_MS = 200;

function spawnLoop() {
  clearTimeout(spawnTimeout);

  const dayDef = getCurrentDayDef();

  if (
    !isPaused &&
    !tutorialActive &&
    dayDef &&
    customers.length < dayDef.maxOnScreen &&
    (continuousMode || customersSpawnedToday < dayDef.customerCount)
  ) {
    spawnCustomer();
  }

  const nextDelay = 700 + Math.random() * 1000;
  spawnTimeout = setTimeout(spawnLoop, nextDelay);
}

// Shared markup for every customer, however they're spawned (the normal
// random loop, or the tutorial's scripted customers) -- includes the
// order bubble (colored by data-recipe-id, see style.css), the patience
// track/fill (a thin bar along the bubble's bottom edge, filled in by
// updatePatienceBar as remainingMs counts down -- see startCustomerTicker),
// and the customer's face.
function buildCustomerElement(recipe, face, id) {
  const el = document.createElement("div");
  el.className = "customer";
  el.onclick = function () {
    serveCustomer(id);
  };

  el.innerHTML =
    '<div class="order-bubble" data-recipe-id="' + recipe.id + '">' +
    '<span class="order-icon-circle">' + recipe.icon + "</span>" +
    '<div class="patience-track"><div class="patience-fill"></div></div>' +
    "</div>" +
    '<div class="customer-face">' + face + "</div>";

  return el;
}

function spawnCustomer() {
  const id = nextCustomerId++;
  const availableRecipes = recipesUnlockedByDay(currentDay);
  const recipe = availableRecipes[Math.floor(Math.random() * availableRecipes.length)];
  const face = createRandomCharacterSVG();
  const el = buildCustomerElement(recipe, face, id);

  document.getElementById("customerLane").appendChild(el);

  const customer = {
    id: id,
    element: el,
    recipe: recipe,
    remainingMs: PATIENCE_MS,
    warned: false,
    noPatience: !!getCurrentDayDef().noPatience,
    // Set the instant they're served or given up (see serveCustomer /
    // customerGaveUp) -- guards against double-counting the same customer
    // toward customersResolvedToday, see the note above serveCustomer.
    resolved: false
  };
  customers.push(customer);
  customersSpawnedToday += 1;

  // Position at the back of the line (its current index)
  positionCustomer(customer, customers.length - 1);

  // Trigger the slide-in on the next frame so the transition actually plays
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      el.classList.add("parked");
    });
  });

  updateCustomerReadiness(customer);
}

// Single ticking clock drives every customer's patience countdown.
// It simply does nothing while the game is paused, which is what
// makes pausing/resuming trivial (no timers to reschedule).
function startCustomerTicker() {
  clearInterval(customerTickInterval);

  customerTickInterval = setInterval(function () {
    if (isPaused) {
      return;
    }

    // Snapshot the array since customerGaveUp() may remove entries mid-loop
    customers.slice().forEach(function (customer) {
      // Tutorial practice customers have no patience limit -- see
      // spawnTutorialCustomer -- so they never trigger customerGaveUp.
      if (customer.noPatience) {
        return;
      }

      customer.remainingMs -= TICK_MS;
      updatePatienceBar(customer);

      if (!customer.warned && customer.remainingMs <= WARNING_MS) {
        customer.warned = true;
        customer.element.classList.add("impatient");
        setCharacterMouth(customer.element, "straight");
      }

      if (customer.remainingMs <= 0) {
        customerGaveUp(customer.id);
      }
    });
  }, TICK_MS);
}

// Fills the thin bar along the bottom of the order bubble as the customer's
// patience runs out -- empty when they arrive, full red right before they
// give up. Replaces the old sudden red-border swap with a continuous cue.
function updatePatienceBar(customer) {
  const fill = customer.element.querySelector(".patience-fill");
  if (!fill) {
    return;
  }

  const elapsedPct = Math.max(0, Math.min(100, (1 - customer.remainingMs / PATIENCE_MS) * 100));
  fill.style.width = elapsedPct + "%";
}

function positionCustomer(customer, index) {
  customer.element.style.setProperty("--park-right", CUSTOMER_SLOTS[index]);
}

function repositionQueue() {
  customers.forEach(function (customer, index) {
    positionCustomer(customer, index);
  });
}

function customerGaveUp(id) {
  const customer = customers.find(function (c) { return c.id === id; });

  // The resolved guard matters here: serveCustomer() leaves a served
  // customer in the `customers` array for 350ms (so its sparkle/slide-out
  // can play) before actually removing it -- see removeFromQueue below.
  // The patience ticker runs every 200ms and doesn't know a customer was
  // just served, so if that customer's patience had already ticked down
  // to 0 (e.g. served right at the last second), this function could
  // still fire for the SAME customer during that 350ms window, double-
  // counting them toward customersResolvedToday. That let the day-end
  // check (see checkDayProgress) trigger a customer early -- ending the
  // day, and popping up the recap, while a genuinely unserved customer
  // was still sitting on screen (2026-09-21, per Kayla: "it didn't let me
  // serve my last customer before the popup came up").
  if (!customer || customer.resolved) {
    return;
  }
  customer.resolved = true;

  showMessage("A customer left without ordering.");

  if (!customer.isTutorialCustomer) {
    missedToday += 1;
    customersResolvedToday += 1;
  }

  removeFromQueue(customer);

  if (!customer.isTutorialCustomer) {
    checkDayProgress();
  }
}

// ==========================================
// SERVE ORDER (tap a customer)
// ==========================================

function serveCustomer(id) {
  const customer = customers.find(function (c) { return c.id === id; });

  // See the matching guard/comment in customerGaveUp -- a customer stays
  // in the `customers` array for 350ms after being served (for the
  // sparkle/slide-out animation), so it's still possible to tap the same
  // customer again, or for its patience timer to expire, during that
  // window. The resolved flag makes sure only the first resolution
  // (whichever happens first) actually counts.
  if (!customer || customer.resolved) {
    return;
  }

  if (!buildMatchesRecipe(customer.recipe)) {
    showMessage("That's not quite what they ordered! Check the build.");
    customer.element.classList.add("shake");
    setTimeout(function () {
      customer.element.classList.remove("shake");
    }, 300);
    return;
  }

  customer.resolved = true;

  for (const type of SUPPLY_TYPES) {
    build[type] = 0;
  }
  buildOrder = [];

  cash += customer.recipe.price;
  totalEarned += customer.recipe.price;
  ordersServed += 1;

  if (customer.recipe.needs.tea) {
    teaOrdersServed += 1;
  }

  const countsTowardDay = !customer.isTutorialCustomer || customer.countsTowardDay;

  if (countsTowardDay) {
    servedToday += 1;
    earnedToday += customer.recipe.price;
    customersResolvedToday += 1;
  }

  showMessage(customer.recipe.name + " served! +$" + customer.recipe.price.toFixed(2));

  createSparkleBurst(customer.element);

  // Give the sparkle a beat to actually be seen before the customer slides out
  setTimeout(function () {
    removeFromQueue(customer);
  }, 350);

  updateDisplay();

  if (countsTowardDay) {
    checkDayProgress();
  }

  if (tutorialFirstServePending && ordersServed === 1) {
    // A tutorial player's very first served customer gets a special cheer
    // popup instead of the usual toast -- see showTutorialCheer.
    tutorialFirstServePending = false;
    showTutorialCheer("You served your first customer! Keep the line moving until you've served everyone -- then it's time to close up shop for the day.");
  }

  if (tutorialCustomerId === id) {
    advanceTutorialLiveStep();
  }
}

function removeFromQueue(customer) {
  customer.element.classList.add("leaving");
  customer.element.classList.remove("parked");

  setTimeout(function () {
    customer.element.remove();
  }, 500);

  customers = customers.filter(function (c) { return c.id !== customer.id; });

  // Close the gap: everyone behind moves up one spot
  repositionQueue();
}

function updateCustomerReadiness(customer) {
  // Only "ready" is a real visual state now (green ring, current build
  // matches this order) -- there's no more "missing" styling, since the
  // bubble's default/no-match state is just its plain recipe-color circle
  // with no outline (see .order-bubble in style.css, 2026-08-28).
  const bubble = customer.element.querySelector(".order-bubble");
  bubble.classList.toggle("ready", buildMatchesRecipe(customer.recipe));
}

function updateAllCustomerReadiness() {
  customers.forEach(updateCustomerReadiness);
}

// ==========================================
// SPARKLE BURST (light, brief pop on serve)
// ==========================================

function createSparkleBurst(customerEl) {
  for (let i = 0; i < 4; i++) {
    const sparkle = document.createElement("div");
    sparkle.className = "sparkle";
    sparkle.innerHTML = randomStarSVG();

    const angle = Math.random() * Math.PI * 2;
    const distance = 18 + Math.random() * 24;
    const sx = Math.cos(angle) * distance;
    const sy = Math.sin(angle) * distance;

    sparkle.style.setProperty("--sx", sx + "px");
    sparkle.style.setProperty("--sy", sy + "px");

    customerEl.appendChild(sparkle);

    setTimeout(function () {
      sparkle.remove();
    }, 450);
  }
}

// ==========================================
// RECIPE GUIDE
// ==========================================

// Cups and ice always lead a recipe's ingredient row (2026-09-21, per
// Kayla: "make sure it always starts with cup then ice, then list the
// others after but those should always lead"), whatever order the rest of
// the ingredients happen to need -- every recipe needs both today, so this
// always applies in practice, but a recipe that somehow skipped one would
// just fall through to whatever it does need.
const INGREDIENT_LEAD_ORDER = ["cups", "ice"];

function buildIngredientsHTML(recipe) {
  let html = '<div class="recipe-ingredients">';

  // Cup, then ice, then everything else in the recipe's OWN declared order
  // (its `needs` object, in the order it's written in RECIPES above) --
  // e.g. Lemon Tea reads cup/ice/tea/lemon, not cup/tea/ice/lemon.
  const remainingTypes = Object.keys(recipe.needs).filter(function (type) {
    return INGREDIENT_LEAD_ORDER.indexOf(type) === -1;
  });
  const orderedTypes = INGREDIENT_LEAD_ORDER.concat(remainingTypes);

  orderedTypes.forEach(function (type) {
    const amount = recipe.needs[type];
    if (amount) {
      // Every current recipe only ever needs 1 of an ingredient, so the
      // count is just noise -- only show "xN" if a future recipe needs
      // more than one of something.
      const countLabel = amount > 1 ? "<em>x" + amount + "</em>" : "";
      html +=
        '<span class="recipe-ingredient">' +
        ingredientIconHTML(type) +
        countLabel + "</span>";
    }
  });

  html += "</div>";
  return html;
}

function buildRecipeListHTML(recipeList) {
  let html = "";

  recipeList.forEach(function (recipe) {
    // Drink icon -- title -- ingredients, all on one line, with the
    // ingredients pushed to the row's far right via .recipe-ingredients'
    // margin-left:auto (see the shared #recipeBox/#dayRecapBox scoped CSS
    // in style.css -- both modals' recipe lists use this exact layout).
    // data-recipe-id drives each row's pale background color (see
    // style.css) so a given recipe is always the same color everywhere,
    // regardless of which popup shows it or how many other rows are
    // present -- e.g. Iced Tea reads as peach in both the full Recipe
    // Guide AND the "new recipes unlocked" popup that only shows 2 rows,
    // rather than colors shifting with each list's own row position.
    html += '<div class="recipe-entry" data-recipe-id="' + recipe.id + '">';
    html += '<div class="recipe-result">' + recipe.icon + "</div>";
    html += '<div class="recipe-info"><strong>' + recipe.name + "</strong></div>";
    html += buildIngredientsHTML(recipe);
    html += "</div>";
  });

  return html;
}

function populateRecipeGuide() {
  const container = document.getElementById("recipeList");
  container.innerHTML = buildRecipeListHTML(recipesUnlockedByDay(currentDay));
}

function openRecipeGuide() {
  pauseGame();
  document.getElementById("recipeBox").classList.remove("hidden");
}

function closeRecipeGuide() {
  document.getElementById("recipeBox").classList.add("hidden");
  resumeGame();
}

// ==========================================
// SAVE MONEY
// Only callable from the end-of-day recap popup now (see #dayRecapBox) --
// there's no mid-day way to move cash into savings any more, so the day
// stays focused on serving customers instead of account-juggling.
// ==========================================

function saveMoney(amount) {
  if (cash < amount) {
    showMessage("You don't have enough cash to save that much!");
    return;
  }

  cash -= amount;
  savings += amount;
  savingsAddedThisRecap += amount;

  updateDisplay();
  updateDayRecapMoneyStats();
}

// Puts back exactly what the player has added to savings during THIS
// viewing of the recap popup (see savingsAddedThisRecap above) -- lets
// them back out of adding too much without having to know or type an
// exact amount. Disabled/no-ops once there's nothing to undo.
function undoSavings() {
  if (savingsAddedThisRecap <= 0) {
    return;
  }

  savings -= savingsAddedThisRecap;
  cash += savingsAddedThisRecap;
  savingsAddedThisRecap = 0;

  updateDisplay();
  updateDayRecapMoneyStats();
}

// ==========================================
// DAY PROGRESS
// A day has no goals to hit any more -- the customer count itself is the
// challenge. Once every customer for the day has been resolved (served OR
// walked away), the day ends and the recap popup takes over.
// ==========================================

function getCurrentDayDef() {
  return GAME_DAYS[currentDay - 1];
}

function checkDayProgress() {
  // Endless play once "Keep Playing" is chosen on the finale recap (see
  // startContinuousPlay) -- no customer count ever ends the day again.
  if (continuousMode) return;

  const dayDef = getCurrentDayDef();
  if (!dayDef) return;

  if (customersResolvedToday >= dayDef.customerCount) {
    endDay();
  }
}

// ==========================================
// END OF DAY / RECAP POPUP
// Fires once every customer for the day has been resolved. Styled after
// Budget Builder's stage-recap popup (per Kayla): a dark "statement" card
// with the day's stats and a place to move cash into savings before
// tomorrow. Looks identical every day (2026-09-21, per Kayla) -- no
// recipe list here any more. When the day that's about to start adds new
// recipes, a SEPARATE plain-white popup (#recipeUnlockBox) shows those
// right after this one closes -- see handleDayRecapAction/showRecipeUnlock
// below for the two-popup sequence.
//
// (2026-09-21, per Kayla) The "CLOSED" sign pops onto the stand first --
// game stays paused/dimmed the moment the last customer is resolved, same
// as any other popup, but the recap card itself waits so the sign has a
// beat on screen before the stats appear. Started at 1s; bumped to 3s per
// Kayla ("give it like a couple more seconds"), then per her follow-up
// ("a little too long, shave off 2 secds") brought back down to 1s --
// same value it started at, just confirmed as the right one this time.
// ==========================================

const CLOSED_SIGN_DELAY_MS = 1000;

function endDay() {
  pauseGame();
  showClosedSign();
  setTimeout(function () {
    populateDayRecap();
    document.getElementById("dayRecapBox").classList.remove("hidden");
  }, CLOSED_SIGN_DELAY_MS);
}

// Restarts the CSS pop-in animation even on repeat days -- toggling the
// class off and forcing a reflow (the .offsetWidth read) before adding it
// back is what makes @keyframes closed-sign-pop replay from 0% instead of
// silently no-op'ing because the class was technically already present.
function showClosedSign() {
  const sign = document.getElementById("closedSign");
  sign.classList.remove("hidden");
  sign.classList.remove("sign-appear");
  void sign.offsetWidth;
  sign.classList.add("sign-appear");
}

function hideClosedSign() {
  const sign = document.getElementById("closedSign");
  sign.classList.add("hidden");
  sign.classList.remove("sign-appear");
}

function populateDayRecap() {
  const dayDef = getCurrentDayDef();
  const nextDayDef = GAME_DAYS[currentDay]; // GAME_DAYS is 0-indexed; currentDay (1-indexed) already points at the next day's def, if any

  // The last day has no "tomorrow" to hand off to -- instead of the usual
  // day-to-day recap, this is the finale: whole-game lifetime stats (per
  // Kayla: "stats for the entire games customers, checking, savings etc"),
  // a bigger/more celebratory popup (see .finale in style.css), and a
  // choice instead of a single "next day" button -- Start Over (the old
  // Play Again behavior) or Keep Playing on in endless mode (see
  // startContinuousPlay/confirmRestart below).
  const isFinale = !nextDayDef;
  document.getElementById("dayRecapBox").classList.toggle("finale", isFinale);

  const servedLabel = document.getElementById("dayRecapServedLabel");
  const cashLabel = document.getElementById("dayRecapCashLabel");
  const finaleGrid = document.getElementById("dayRecapFinaleGrid");
  const savingsDivider = document.getElementById("dayRecapSavingsDivider");
  const savingsCard = document.getElementById("dayRecapSavingsCard");
  const nextBtn = document.getElementById("dayRecapNextBtn");
  const finaleActions = document.getElementById("dayRecapFinaleActions");

  // Fresh popup, fresh undo history -- whatever was added to savings on a
  // previous day (or earlier viewing of this same popup) isn't something
  // this Undo button should be able to touch.
  savingsAddedThisRecap = 0;

  if (isFinale) {
    // Laid out like Budget Builder's grand finale (2026-09-23, per Kayla):
    // "You Did It!" (the "All 6 Days Complete" eyebrow was removed per
    // Kayla), then a big white hero card with the final
    // total (Checking + Savings added together), with the four whole-game
    // stats on glassy tiles underneath (see .finale rules in style.css).
    document.getElementById("dayRecapTitle").textContent = "You Did It!";
    document.getElementById("dayRecapMessage").textContent =
      "You ran your stand for " + GAME_DAYS.length + " days. Here's what you built.";

    const finalTotal = Math.round((cash + savings) * 100) / 100;
    document.getElementById("dayRecapTotalNote").textContent =
      "$" + cash.toFixed(2) + " in checking + $" + savings.toFixed(2) + " in savings";
    document.getElementById("dayRecapTotalHero").classList.remove("hidden");
    countUpMoney(document.getElementById("dayRecapTotal"), finalTotal);

    servedLabel.textContent = "Customers Served";
    document.getElementById("dayRecapServed").textContent = String(ordersServed);
    cashLabel.textContent = "Checking";

    document.getElementById("dayRecapFinalSavings").textContent = "$" + savings.toFixed(2);
    // Whole-game supply spending (swapped in for Total Earned, 2026-09-23,
    // per Kayla -- the hero card already covers what they earned).
    document.getElementById("dayRecapFinalSpent").textContent = "$" + totalSpent.toFixed(2);
    finaleGrid.classList.remove("hidden");

    // No more "tomorrow" to save cash for once the game's over, so the
    // interactive add/undo savings card steps aside for the plain finale
    // stat above.
    savingsDivider.classList.add("hidden");
    savingsCard.classList.add("hidden");

    nextBtn.classList.add("hidden");
    finaleActions.classList.remove("hidden");

    // Falling confetti inside the finale popup (2026-09-23).
    startPopupConfetti(document.getElementById("dayRecapBox"));
  } else {
    document.getElementById("dayRecapTitle").textContent = "Day " + currentDay + " Complete!";
    document.getElementById("dayRecapMessage").textContent =
      "Nice work! Your cash and savings carry into tomorrow.";

    document.getElementById("dayRecapTotalHero").classList.add("hidden");

    servedLabel.textContent = "Customers Served";
    document.getElementById("dayRecapServed").textContent = servedToday + " / " + dayDef.customerCount;
    cashLabel.textContent = "Checking Account";

    finaleGrid.classList.add("hidden");
    savingsDivider.classList.remove("hidden");
    savingsCard.classList.remove("hidden");

    nextBtn.classList.remove("hidden");
    nextBtn.textContent = "Start Day " + nextDayDef.day;
    finaleActions.classList.add("hidden");

    stopPopupConfetti(document.getElementById("dayRecapBox"));
  }

  updateDayRecapMoneyStats();
}

// Counts a dollar amount up from $0 for the finale's hero card, same feel
// as Budget Builder's "YOU SAVED" number. Jumps straight to the value when
// the player prefers reduced motion.
let countUpToken = 0;
function countUpMoney(el, target) {
  const token = ++countUpToken;
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduce || target <= 0) {
    el.textContent = "$" + target.toFixed(2);
    return;
  }
  const duration = 1400;
  const start = performance.now();
  function step(now) {
    if (token !== countUpToken) return;
    const t = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - t, 3);
    el.textContent = "$" + (target * eased).toFixed(2);
    if (t < 1) requestAnimationFrame(step);
  }
  el.textContent = "$0.00";
  requestAnimationFrame(step);
}

// Keeps the recap popup's Checking/Savings numbers -- and the Undo
// button's enabled state -- live as the player taps +$1/+$5/+$10 or Undo,
// without needing to close and reopen the popup.
function updateDayRecapMoneyStats() {
  document.getElementById("dayRecapCash").textContent = "$" + cash.toFixed(2);
  document.getElementById("dayRecapSavings").textContent = "$" + savings.toFixed(2);
  document.getElementById("undoSaveBtn").disabled = savingsAddedThisRecap <= 0;
}

function revealNewSupplies(dayDef) {
  if (!dayDef.newRecipeIds) return;

  const newSupplyTypes = new Set();
  dayDef.newRecipeIds.forEach(function (recipeId) {
    const recipe = RECIPES.find(function (r) { return r.id === recipeId; });
    if (recipe) {
      Object.keys(recipe.needs).forEach(function (type) { newSupplyTypes.add(type); });
    }
  });

  newSupplyTypes.forEach(function (type) {
    const shopItem = document.querySelector('.shop-item[data-supply="' + type + '"]');
    const invSlot = document.querySelector('.inv-slot[data-supply="' + type + '"]');
    if (shopItem) shopItem.classList.remove("hidden");
    if (invSlot) invSlot.classList.remove("hidden");
  });
}

// The recap popup's "Start Day N" button (every day but the last) -- opens
// the "new recipes" popup when the day about to start unlocks any, or
// jumps straight into the next day when it doesn't. The last day's recap
// shows a two-button choice instead (Start Over / Keep Playing -- see
// #dayRecapFinaleActions in populateDayRecap and confirmRestart/
// startContinuousPlay below), so this function isn't reached from there;
// the fallback is kept as a safety net in case it ever is.
function handleDayRecapAction() {
  document.getElementById("dayRecapBox").classList.add("hidden");

  const nextDayDef = GAME_DAYS[currentDay];

  if (!nextDayDef) {
    confirmRestart();
    return;
  }

  if (nextDayDef.newRecipeIds) {
    showRecipeUnlock(nextDayDef);
  } else {
    startNextDay();
  }
}

// Plain white "new recipes" popup (not the dark .statement treatment) --
// this is what #levelUpBox used to look like before the days-of-business
// rework. The game is already paused from endDay() and stays paused
// straight through into this popup, so there's no flash of live gameplay
// showing through in between the two.
function showRecipeUnlock(dayDef) {
  document.getElementById("recipeUnlockMessage").textContent =
    dayDef.unlockMessage || "New recipes unlocked!";

  const newRecipes = RECIPES.filter(function (r) {
    return dayDef.newRecipeIds.indexOf(r.id) !== -1;
  });
  document.getElementById("recipeUnlockList").innerHTML = buildRecipeListHTML(newRecipes);

  document.getElementById("recipeUnlockBox").classList.remove("hidden");
}

function closeRecipeUnlock() {
  document.getElementById("recipeUnlockBox").classList.add("hidden");
  startNextDay();
}

function startNextDay() {
  currentDay += 1;

  // Savings grows a little every day it carries over -- see
  // SAVINGS_INTEREST_RATE above. Rounded to the nearest cent so it can
  // never add a fraction of a cent the display doesn't show.
  if (savings > 0) {
    const interestEarned = Math.round(savings * SAVINGS_INTEREST_RATE * 100) / 100;
    if (interestEarned > 0) {
      savings += interestEarned;
      showMessage("Your savings earned $" + interestEarned.toFixed(2) + " in interest overnight!");
    }
  }

  hideClosedSign();
  revealNewSupplies(getCurrentDayDef());
  populateRecipeGuide();

  customersSpawnedToday = 0;
  customersResolvedToday = 0;
  servedToday = 0;
  missedToday = 0;
  earnedToday = 0;
  spentToday = 0;

  // Supplies do NOT carry over day to day (per Kayla) -- whatever's left
  // in the shop inventory at closing time is gone once the new day opens,
  // same as the in-progress build tray (which should already be empty by
  // now since a day only ends once every customer is resolved, but this
  // clears it too as a safety net rather than leaving a stale half-built
  // order sitting on top of a zeroed-out inventory).
  SUPPLY_TYPES.forEach(function (type) {
    inventory[type] = 0;
    build[type] = 0;
  });
  buildOrder = [];

  resumeGame();
  updateDisplay();
}

// "Keep Playing" on the finale recap (see populateDayRecap/
// #dayRecapFinaleActions) -- endless play on the last day's recipes and
// settings (currentDay/getCurrentDayDef are left alone, so Day 6's def
// keeps applying forever), no customer-count cutoff (see continuousMode
// in checkDayProgress/spawnLoop). Otherwise mirrors startNextDay's reset
// of the day's counters and supplies -- no carryover into endless mode
// either. Savings stops earning interest once this starts, since
// startNextDay (where interest is applied) is never called again --
// flagged as an assumption for Kayla in the status doc.
function startContinuousPlay() {
  continuousMode = true;

  document.getElementById("dayRecapBox").classList.add("hidden");
  document.getElementById("dayRecapBox").classList.remove("finale");
  hideClosedSign();

  customersSpawnedToday = 0;
  customersResolvedToday = 0;
  servedToday = 0;
  missedToday = 0;
  earnedToday = 0;
  spentToday = 0;

  SUPPLY_TYPES.forEach(function (type) {
    inventory[type] = 0;
    build[type] = 0;
  });
  buildOrder = [];

  resumeGame();
  updateDisplay();
}

// ==========================================
// UPDATE DISPLAY
// ==========================================

function updateDisplay() {
  document.getElementById("cash").textContent = "$" + cash.toFixed(2);
  document.getElementById("savings").textContent = "$" + savings.toFixed(2);

  for (const type of SUPPLY_TYPES) {
    document.getElementById("count-" + type).textContent = inventory[type];
  }

  updateBuildDisplay();
  updateAllCustomerReadiness();
}

// ==========================================
// MESSAGE STRIP
// ==========================================

function showMessage(message) {
  document.getElementById("messageBox").textContent = message;
}

// ==========================================
// RESTART (in-page confirm, no native dialog)
// ==========================================

function restartGame() {
  pauseGame();
  document.getElementById("confirmBox").classList.remove("hidden");
}

function closeConfirm() {
  document.getElementById("confirmBox").classList.add("hidden");
  resumeGame();
}

function confirmRestart() {
  cash = 10.00;
  savings = 0;
  inventory = { cups: 0, lemons: 0, ice: 0, sugar: 0, tea: 0 };
  build = { cups: 0, lemons: 0, ice: 0, sugar: 0, tea: 0 };
  buildOrder = [];

  totalEarned = 0;
  totalSpent = 0;
  ordersServed = 0;
  teaOrdersServed = 0;

  continuousMode = false;

  currentDay = 1;
  customersSpawnedToday = 0;
  customersResolvedToday = 0;
  servedToday = 0;
  missedToday = 0;
  earnedToday = 0;
  spentToday = 0;

  document.querySelectorAll(".shop-item, .inv-slot").forEach(function (el) {
    if (el.dataset.supply === "tea") {
      el.classList.add("hidden");
    }
  });
  populateRecipeGuide();

  document.getElementById("confirmBox").classList.add("hidden");
  document.getElementById("dayRecapBox").classList.add("hidden");
  document.getElementById("dayRecapBox").classList.remove("finale");
  document.getElementById("recipeUnlockBox").classList.add("hidden");
  document.getElementById("recipeBox").classList.add("hidden");
  hideClosedSign();

  // Clear out any in-progress tutorial (spotlight card, callout, cheer
  // popup, scripted no-patience customer) so a restart mid-tutorial
  // doesn't leave stray UI or a stuck customer behind.
  hideTutorialPoint();
  hideTutorialCallout();
  document.getElementById("tutorialCheerBox").classList.add("hidden");
  tutorialPointStep = -1;
  tutorialActive = false;
  tutorialLiveStep = null;
  tutorialCustomerId = null;
  tutorialFirstServePending = false;

  document.getElementById("customerLane").innerHTML = "";
  customers = [];

  showMessage("Welcome back! Let's build your lemonade empire!");

  updateDisplay();

  // Back to the intro popup (2026-09-23, per Kayla) instead of dropping
  // straight into play, so the player can pick Start or Tutorial again --
  // same as Driver Decides' and Coin Catch's restart. showTutorial()
  // keeps the game paused until they choose.
  showTutorial();
}


/* ================= POPUP CONFETTI (final popup) =================
   Same falling confetti as Budget Builder's grand finale
   (2026-09-23, per Kayla). Adds a .popup-confetti layer as the
   popup box's first child and fills it with looping pieces; the
   layer sits behind the popup's content (see style.css). Call
   stopPopupConfetti() whenever the same box is shown for a
   non-final result so the confetti doesn't carry over. */

const POPUP_CONFETTI_COLORS = ["#FF25BA", "#FF9D25", "#ffffff", "#59D2FE", "#8BD1FF"];

function startPopupConfetti(box) {
  if (!box) {
    return;
  }
  let layer = box.querySelector(":scope > .popup-confetti");
  if (!layer) {
    layer = document.createElement("div");
    layer.className = "popup-confetti";
    layer.setAttribute("aria-hidden", "true");
    box.insertBefore(layer, box.firstChild);
  }
  layer.innerHTML = "";
  for (let n = 0; n < 32; n++) {
    const piece = document.createElement("span");
    piece.style.left = `${Math.random() * 100}%`;
    piece.style.background = POPUP_CONFETTI_COLORS[n % POPUP_CONFETTI_COLORS.length];
    piece.style.animationDelay = `${(Math.random() * 4).toFixed(2)}s`;
    piece.style.animationDuration = `${(3.2 + Math.random() * 2.6).toFixed(2)}s`;
    piece.style.setProperty("--spin", `${Math.round(Math.random() * 720 - 360)}deg`);
    piece.style.setProperty("--drift", `${Math.round(Math.random() * 120 - 60)}px`);
    layer.appendChild(piece);
  }
}

function stopPopupConfetti(box) {
  const layer = box && box.querySelector(":scope > .popup-confetti");
  if (layer) {
    layer.innerHTML = "";
  }
}
